const D=window.WARDOGS, main=document.querySelector('main');
const discord=(label='Join Discord',cls='button primary')=>`<a class="${cls}" href="${D.discord}" target="_blank" rel="noopener noreferrer">${label} <span>↗</span></a>`;
const badge=s=>`<span class="badge ${s}"><i class="dot"></i>${s}</span>`;
const heading=(eyebrow,title,desc='')=>`<section class="pagehead"><p class="eyebrow">${eyebrow}</p><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</section>`;
const rules=`<ol class="rules"><li><strong>Respect the people behind the players.</strong> No harassment, hate speech, threats or targeted abuse.</li><li><strong>Keep the game fair.</strong> No cheats, exploits or deliberate disruption. Report suspected cheating privately to staff.</li><li><strong>Play for the squad.</strong> Follow the game mode and staff instructions. Server-specific settings will be published before launch.</li><li><strong>Keep personal information private.</strong> Don’t post someone else’s details or private messages.</li><li><strong>Give staff the details.</strong> For reports, include the server, approximate time and evidence where available. Appeals go through Discord.</li></ol><p class="note">Draft community rules · Final rules and moderation process will be confirmed before launch.</p>`;
function serverCard(s){return `<article class="servercard"><div class="server-top"><span class="server-id">ZA / ${s.id==='za-01'?'01':'02'}</span>${badge(s.status)}</div><div class="server-graphic" aria-hidden="true"><span>${s.slots}</span><small>PLAYER SLOTS</small><div class="crosshair">+</div></div><div class="server-body"><p class="eyebrow">${s.game} <span> / </span> ${s.region}</p><h3>${s.name}</h3><div class="servermeta"><span>Players <b>${s.players===null?'—':s.players} / ${s.slots}</b></span><span>Host <b>${s.host}</b></span></div><p class="small muted">${s.status==='planned'?'Coming soon · Player count not connected':'Player count not connected'}</p><a class="textlink" href="#server/${s.id}">View server <span>↗</span></a></div></article>`;}
function news(){return D.announcements.map(a=>`<article class="news"><div class="newsmeta"><span>${a.tag}</span><time>${a.date}</time></div><h3>${a.title}</h3><p>${a.body}</p></article>`).join('');}
const map=`<svg class="terrain" viewBox="0 0 800 700" aria-hidden="true"><defs><pattern id="grid" width="50" height="50" patternUnits="userSpaceOnUse"><path d="M50 0H0V50" fill="none" stroke="#899277" stroke-opacity=".12"/></pattern></defs><rect width="800" height="700" fill="url(#grid)"/><g fill="none" stroke="#80916c" stroke-width="1.5" opacity=".3"><path d="M30 700C-50 420 250 480 170 280S340-20 560 20 650 250 800 270"/><path d="M70 700C-10 440 300 470 210 280S350 20 550 60 640 300 800 310"/><path d="M110 700C50 470 340 460 250 290S380 60 540 100 650 330 800 350"/><path d="M150 700C110 490 380 470 290 300S400 100 530 140 660 370 800 390"/><path d="M190 700C170 510 410 480 330 320S430 140 520 180 670 410 800 430"/><path d="M230 700C230 520 450 500 370 340S450 180 510 220 680 450 800 470"/><path d="M270 700C290 540 480 520 410 360S480 220 510 260 700 500 800 510"/><path d="M310 700C350 560 520 550 450 390S500 280 520 310 720 530 800 550"/></g><path d="M280 520 440 350 590 420 660 240" stroke="#dca94e" opacity=".45" fill="none" stroke-dasharray="5 7"/><g fill="#dca94e"><circle cx="440" cy="350" r="5"/><circle cx="590" cy="420" r="5"/></g><g fill="none" stroke="#dca94e" opacity=".45"><circle cx="440" cy="350" r="20"/><circle cx="590" cy="420" r="20"/></g></svg>`;
function home(){return `<section class="hero"><div class="hero-copy"><p class="eyebrow"><span class="tinyline"></span> WARDOGS ZUID AFRIKA</p><h1>FIND YOUR<br>SQUAD.<br><span>HOLD YOUR<br>GROUND.</span></h1><p>A new home for Wardogs in South Africa. Two servers, a shared Discord, and a community you can help build from day one.</p><div class="actions">${discord()}<a href="#servers" class="button secondary">Explore servers <span>↓</span></a></div><div class="launch-note"><i class="dot"></i><span>COMING SOON <small>Targeting next week · Date to be confirmed</small></span></div></div><div class="hero-art">${map}<div class="map-label">OPERATIONS / SOUTH AFRICA<br><span>WARDOGS COMMUNITY NETWORK</span></div><div class="map-emblem"><img src="mark.svg" alt="Editable Wardogs community emblem"><span>ZA</span></div><div class="map-node node1"><span>01</span> 50 SLOTS <small>PLANNED</small></div><div class="map-node node2"><span>02</span> 90 SLOTS <small>PLANNED</small></div><div class="art-caption"><span>LOCAL GROUND.<br>SHARED PURPOSE.</span><small>TACTICAL MAP / BRAND CONCEPT</small></div></div></section><section class="numbers"><div><strong>02</strong><span>UPCOMING SERVERS</span></div><div><strong>140</strong><span>PLANNED PLAYER SLOTS</span></div><div><strong>ZA</strong><span>SOUTH AFRICAN HOSTING</span></div><div><strong>01</strong><span>COMMUNITY TO BUILD</span></div></section><section class="section"><div class="sectiontitle"><div><p class="eyebrow">CHOOSE YOUR GROUND</p><h2>Your next deployment.</h2></div><a href="#servers" class="textlink">All servers ↗</a></div><div class="servergrid">${D.servers.map(serverCard).join('')}</div></section><section class="rally"><p class="eyebrow">MORE THAN A SERVER LIST</p><h2>Good games start<br>with good people.</h2><div class="benefits"><div><span>01 / CONNECT</span><h3>Find your people.</h3><p>Meet fellow players, form a squad and find a familiar name on your next match.</p></div><div><span>02 / BUILD</span><h3>Be here from the start.</h3><p>Share feedback while we get set up. Help shape the community you want to play in.</p></div><div><span>03 / BELONG</span><h3>One place to regroup.</h3><p>Discord is our meeting point for launch updates, questions and everything between games.</p></div></div></section><section class="section"><div class="sectiontitle"><div><p class="eyebrow">FROM THE COMMUNITY</p><h2>Latest dispatches.</h2></div><a href="#announcements" class="textlink">All updates ↗</a></div><div class="newsgrid">${news()}</div></section><section class="joinstrip"><div><p class="eyebrow">THE FIRST CHAPTER STARTS WITH YOU</p><h2>Squad up before launch.</h2><p>Join Discord. Say hello. Be ready when the servers open.</p></div>${discord()}</section>`;}
function servers(){return heading('SERVER DIRECTORY','Find your ground.','Two Wardogs servers planned for South Africa, hosted through GG Host. Connection details will be published when ready.')+`<section class="section tight"><div class="filters"><label>Status <select id="status-filter"><option value="all">All statuses</option><option value="planned">Planned</option><option value="testing">Testing</option><option value="live">Live</option><option value="offline">Offline</option></select></label><p id="result-count">2 servers · 140 planned slots</p></div><div class="servergrid" id="server-results">${D.servers.map(serverCard).join('')}</div><div class="legend">${['planned','testing','live','offline'].map(badge).join('')}<span>Status is manually set until monitoring is connected.</span></div></section>`;}
function server(id){let s=D.servers.find(s=>s.id===id);if(!s)return heading('NOT FOUND','Server not found.')+`<a class="button" href="#servers">Back to servers</a>`;return heading('WARDOGS / SOUTH AFRICA',s.name,s.description)+`<section class="section tight"><a class="textlink back" href="#servers">← Server directory</a><div class="detailgrid"><div><div class="panel"><div class="sectiontitle"><h2>Server briefing</h2>${badge(s.status)}</div><dl class="facts"><div><dt>Game</dt><dd>${s.game}</dd></div><div><dt>Region</dt><dd>${s.region}</dd></div><div><dt>Capacity</dt><dd>${s.slots} planned slots</dd></div><div><dt>Current players</dt><dd>Unavailable · integration pending</dd></div><div><dt>Game mode / map</dt><dd>${s.mode}</dd></div><div><dt>Hosting provider</dt><dd>${s.host}</dd></div></dl></div><div class="panel"><h2>How to connect</h2><ol class="rules"><li>Join our Discord for the confirmed launch announcement.</li><li>Once live, open Wardogs and look for the confirmed server name in the community server browser.</li><li>Use the join details published here at launch. Exact instructions depend on the final server configuration.</li></ol><p class="notice">Connection address / join code: not yet supplied.</p>${discord('Get launch updates')}</div><div class="panel"><h2>Community rules</h2>${rules}</div></div><aside><div class="panel amberpanel"><p class="eyebrow">PRE-LAUNCH</p><h2>See you on<br>the ground.</h2><p>${D.launch}</p><p>Join details and settings are being prepared.</p></div><div class="panel"><h3>Server stats</h3><p>Player counts, match history and performance stats are not connected yet.</p><a class="textlink" href="#stats">Explore the stats demo ↗</a></div></aside></div></section>`;}
function memberships(){return heading('KEEP THE COMMUNITY GROWING','Back your home ground.','Join for free. Support us if you want to help build what comes next.')+`<section class="section tight"><div class="membershipgrid"><article class="panel tier"><p class="eyebrow">EVERYONE STARTS HERE</p><h2>Community</h2><div class="price">Free<span>always welcome</span></div><p>Your way into Wardogs Zuid Afrika.</p><ul class="checks"><li>Access to our community Discord</li><li>Play on public servers when they launch</li><li>Community news and launch updates</li><li>A place to find your next squad</li></ul>${discord('Join the community','button secondary')}</article><article class="panel tier supporter"><div class="ribbon">FOR THOSE WHO WANT TO GIVE BACK</div><p class="eyebrow">BUILD IT WITH US</p><h2>Supporter</h2><div class="price">$3<span>USD / month · proposed billing interval</span></div><p>Support the community. Wear it with pride.</p><ul class="checks"><li>Everything in Community</li><li>Supporter Discord role <small>Planned · role sync required</small></li><li>Community recognition <small>Planned · opt-in</small></li><li>Game perks only if supported and permitted <small>No gameplay perks promised at launch</small></li></ul><button class="button primary" data-notice="payments">Memberships coming soon ↗</button><p class="small">No checkout connected. No charges can be made.</p></article></div><p class="note">Price shown in USD. “Roughly R50” is the founder’s estimate, not a fixed exchange rate or a ZAR billing price. Monthly billing is an assumption for review. Final terms, taxes and renewal details must be confirmed before sales open.</p><div class="faq"><p class="eyebrow">GOOD TO KNOW</p><h2>A few quick answers.</h2><details><summary>Do I need to pay to play?</summary><p>The planned Community tier is free. Supporter membership is optional and is intended to help support the community.</p></details><details><summary>Can I subscribe now?</summary><p>Not yet. This preview has no payment connection. A provider sandbox and end-to-end testing come next; real payments require explicit approval.</p></details><details><summary>How will renewals and cancellations work?</summary><p>Proposed: monthly renewal with a member area to view your plan, renewal date, invoices and cancellation options. These features require accounts and a payment provider. Final terms must be shown before checkout.</p></details><details><summary>How will my Discord role appear?</summary><p>After account linking and verified payment, a bot will assign the role. This requires Discord OAuth, a bot with the right permissions, and a payment webhook. None are connected in this preview.</p></details><details><summary>Does membership give an advantage?</summary><p>No gameplay advantage is promised. Any server perks will be reviewed against Wardogs’ rules and technical support before being advertised.</p></details></div></section>`;}
function stats(){return heading('PLAYER INTELLIGENCE','Every squad has a story.','A preview of future player profiles and leaderboards. All names, scores and activity below are fictional demo data.')+`<section class="section tight"><div class="notice"><strong>DEMO DATA</strong> · Not connected to Wardogs or GG Host. These are not real player rankings.</div><div class="filters"><label>Rank by <select id="rank-filter"><option value="score">Score</option><option value="kills">Kills</option><option value="matches">Matches played</option></select></label><span>Wardogs · All demo players</span></div><div class="tablewrap"><table><thead><tr><th>Rank</th><th>Player</th><th>Score</th><th>Kills</th><th>Matches</th><th>Profile</th></tr></thead><tbody id="rankings">${rankRows('score')}</tbody></table></div><div class="panel"><h2>What will make this live?</h2><p>Server identity, a supported read-only stats service or server event feed, persistent storage and player identity mapping. GG Host access and Wardogs’ available data must be verified before promising specific metrics.</p><p>When a feed becomes unavailable, show its last update and an unavailable state. Never substitute demo rankings for live records.</p></div></section>`;}
function rankRows(key){return [...D.demoPlayers].sort((a,b)=>b[key]-a[key]).map((p,i)=>`<tr><td class="rank">0${i+1}</td><td><strong>${p.name}</strong></td><td>${p.score.toLocaleString()}</td><td>${p.kills}</td><td>${p.matches}</td><td><a class="textlink" href="#player/${D.demoPlayers.indexOf(p)}">View ↗</a></td></tr>`).join('');}
function player(id){let p=D.demoPlayers[Number(id)];if(!p)return heading('NOT FOUND','Player not found.');return heading('FICTIONAL PLAYER PROFILE',p.name,'Demo profile · No real account or game activity is represented.')+`<section class="section tight"><a class="textlink back" href="#stats">← Demo leaderboard</a><div class="numbers"><div><strong>${p.score.toLocaleString()}</strong><span>DEMO SCORE</span></div><div><strong>${p.kills}</strong><span>DEMO KILLS</span></div><div><strong>${(p.kills/p.deaths).toFixed(2)}</strong><span>DEMO K/D</span></div><div><strong>${p.matches}</strong><span>DEMO MATCHES</span></div></div><div class="panel"><h2>Recent activity · Demo</h2><p>Illustrative match completed · Server 01 · +450 demo score</p><p>Illustrative squad session · Server 02 · +320 demo score</p></div></section>`;}
function community(){return heading('WELCOME TO WARDOGS ZUID AFRIKA','Your squad starts here.','A South African community for Wardogs players. Join us while we build the first two servers.')+`<section class="section tight"><div class="detailgrid"><div><div class="panel"><h2>Three steps to join.</h2><ol class="rules"><li><strong>Join Discord.</strong> Introduce yourself and check the community rules.</li><li><strong>Follow the launch updates.</strong> We’re targeting next week; the exact date is still to be confirmed.</li><li><strong>Find your server.</strong> Connection details will appear in the directory once ready.</li></ol>${discord()}</div><div class="panel"><h2>Play hard. Treat people well.</h2>${rules}</div></div><aside><div class="panel amberpanel"><p class="eyebrow">NEED A HAND?</p><h2>Talk to us.</h2><p>Join Discord and ask staff where to post support requests. For a player report, include the server, time and evidence. Avoid posting private information publicly.</p>${discord('Open Discord','button secondary')}</div><div class="panel"><h3>Independent community</h3><p>Wardogs Zuid Afrika is our community brand. This site does not claim to be the official Wardogs game website.</p></div></aside></div></section>`;}
function account(){return heading('MEMBER AREA / VISUAL DEMO','Your place in the squad.','This is an interactive demonstration, not a signed-in account. Nothing here changes a real subscription.')+`<section class="section tight"><div class="notice"><strong>DEMO ONLY</strong> · Authentication, billing and Discord syncing are not connected. No personal or card details are collected.</div><div class="detailgrid"><div class="panel"><p class="eyebrow">EXAMPLE MEMBERSHIP</p><h2>Supporter <span class="badge">Demo</span></h2><dl class="facts"><div><dt>Price</dt><dd>$3 USD / month (proposed)</dd></div><div><dt>Renewal</dt><dd id="renewal">Example: one month after activation</dd></div><div><dt>Payment method</dt><dd>No payment method connected</dd></div><div><dt>Discord role</dt><dd>Not synced · integration planned</dd></div></dl><div class="actions"><button class="button secondary" data-notice="billing">Manage billing demo</button><button class="button secondary" id="cancel-demo">Preview cancellation</button></div><p id="cancel-state" role="status" class="small muted">Demo changes last only until you leave this page.</p></div><aside class="panel"><h3>Accounts are coming later.</h3><p>Secure sign-in and a verified payment connection will be needed before real plans, renewals or invoices can appear here.</p><a class="textlink" href="#memberships">Explore memberships ↗</a></aside></div></section>`;}
function staff(){return heading('STAFF ACCESS','Staff tools are not connected.','Content is maintained in the site’s editable source for this first release.')+`<section class="section tight"><div class="panel"><p class="eyebrow">PROTECTED ADMINISTRATION / PLANNED</p><h2>Build the permissions first.</h2><p>A future staff area will manage server status, listings, announcements, tiers and featured content. It needs server-verified sign-in and role-based permissions before any editor is exposed.</p><dl class="facts"><div><dt>Owner</dt><dd>Staff roles, billing configuration and all content</dd></div><div><dt>Editor</dt><dd>Server listings, announcements and featured content</dd></div><div><dt>Moderator</dt><dd>Community support tools only</dd></div></dl><p>No staff login, editor or public write endpoint exists in this preview. A hidden page or browser setting will never grant staff permissions.</p></div></section>`;}
function render(){const route=location.hash.slice(1)||'home', [page,id]=route.split('/');const pages={home,servers,stats,memberships,community,account,staff,announcements:()=>heading('COMMUNITY DISPATCHES','From the ground up.','Launch news and community updates.')+`<section class="section tight"><div class="newsgrid">${news()}</div></section>`};main.innerHTML=page==='server'?server(id):page==='player'?player(id):pages[page]?pages[page]():heading('404','This page is off the map.')+`<a class="button" href="#home">Return home</a>`;document.title=`${page==='home'?'Find your squad':page.charAt(0).toUpperCase()+page.slice(1)} — Wardogs Zuid Afrika`;document.querySelectorAll('nav a').forEach(a=>{const active=a.hash==='#'+page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.querySelector('header').classList.remove('expanded');document.querySelector('.menu').setAttribute('aria-expanded','false');window.scrollTo(0,0);if(location.hash)main.focus({preventScroll:true});
document.querySelector('#status-filter')?.addEventListener('change',e=>{let list=D.servers.filter(s=>e.target.value==='all'||s.status===e.target.value);document.querySelector('#server-results').innerHTML=list.length?list.map(serverCard).join(''):`<div class="empty"><h2>No ${e.target.value} servers yet.</h2><p>We’re still getting ready. Check planned servers or follow Discord for updates.</p>${discord()}</div>`;document.querySelector('#result-count').textContent=`${list.length} server${list.length===1?'':'s'} · ${list.reduce((n,s)=>n+s.slots,0)} planned slots`;});document.querySelector('#rank-filter')?.addEventListener('change',e=>document.querySelector('#rankings').innerHTML=rankRows(e.target.value));document.querySelector('#cancel-demo')?.addEventListener('click',e=>{const cancelled=e.target.dataset.cancelled==='yes';e.target.dataset.cancelled=cancelled?'no':'yes';e.target.textContent=cancelled?'Preview cancellation':'Reset demo';document.querySelector('#renewal').textContent=cancelled?'Example: one month after activation':'Demo: renewal switched off';document.querySelector('#cancel-state').textContent=cancelled?'Demo reset. No real subscription was changed.':'Demo cancellation shown. No real subscription was cancelled or charged.';});}
document.addEventListener('click',e=>{const b=e.target.closest('[data-notice]');if(!b)return;document.querySelector('#notice-body').innerHTML=b.dataset.notice==='payments'?`<p class="eyebrow">MEMBERSHIPS / COMING SOON</p><h2>Thanks for backing the idea.</h2><p>Supporter is planned at $3 USD per month. Checkout is not connected and no payment will be taken. We’ll share membership updates in Discord.</p>${discord()}`:`<p class="eyebrow">BILLING / DEMO</p><h2>Your billing tools will live here.</h2><p>The future billing area will let signed-in members update payment details, see invoices, check renewals and cancel. This demo has no provider connection and changes no billing details.</p>`;document.querySelector('#notice').showModal();});document.querySelector('.menu').addEventListener('click',e=>{let expanded=document.querySelector('header').classList.toggle('expanded');e.currentTarget.setAttribute('aria-expanded',String(expanded));});window.addEventListener('hashchange',render);render();
